type PassageRow={ id:string;prefix:string;model:string;base:string;date:string;opened_at:string;updated_at:string;created_by:string;checks:Passage["checks"];actions:Passage["actions"];discrepancy_details:string;oil_quantity:string;oil_additions:Passage["oilAdditions"]|null;notes:string;revision:number };
type AlertInfo={ flight_id:string;minutes_before:number;enabled:boolean;status:"scheduled"|"sent"|"failed"|"closed"|"expired";status_detail?:string|null;last_attempt_at?:string|null;last_delivered_at?:string|null;closed_reason?:string|null };

