  const [peopleManagementOpen,setPeopleManagementOpen]=useState(false);
  const [managementOpen,setManagementOpen]=useState(false);
  const [aiOpen,setAiOpen]=useState(false);
  const [trashOpen,setTrashOpen]=useState(false);
