  const [flightViews,setFlightViews]=useState<Set<FlightView>>(()=>new Set(["launched","flying"]));
  const [flightFilterOpen,setFlightFilterOpen]=useState(false);
  const [syncReady,setSyncReady]=useState(false);
  const [syncError,setSyncError]=useState("");
  const [alerts,setAlerts]=useState<Record<string,AlertInfo>>({});
  const [testingAlert,setTestingAlert]=useState<string|null>(null);
  const lastRemoteState=useRef("");
  const lastRemoteCatalogs=useRef("");
  const pendingMutations=useRef(0);
  const passageSaveTimers=useRef(new Map<string,{timer:number;patch:Partial<Passage>}>());
  const localSnapshot=useRef({flights,catalogs});
